(() => {
  const Z=window.Zucco,{state,ROUTES:R,icon:I,avatar:A,btn:BT,escape:E}=Z;
  const NAV=Z.navigation;
  const routeTitles=Z.routeTitles;
  Z.render=()=>{
    if(state.page===R.LOGIN){document.getElementById('app').innerHTML=Z.renderers[R.LOGIN]();document.title='Sign in · Zucco';return;}
    const crumbs=routeTitles[state.page]||routeTitles[R.LEADS];
    let lastGroup='';
    const navigation=NAV.map(n=>{const group=n.group!==lastGroup;lastGroup=n.group;return `${group?`${n===NAV[0]?'':'</nav>'}<p class="nav-group-label">${n.group}</p><nav class="navigation" aria-label="${n.group}">`:''}<button class="nav-link ${(state.page===n.route||(n.route===R.STUDENTS&&state.page===R.STUDENT)||(n.route===R.COURSES&&state.page===R.COURSE)||(n.route===R.GROUPS&&state.page===R.GROUP)||(n.route===R.SETTINGS&&state.page===R.ROLES))?'active':''}" type="button" data-action="go:${n.route}" ${(state.page===n.route||(n.route===R.STUDENTS&&state.page===R.STUDENT)||(n.route===R.COURSES&&state.page===R.COURSE)||(n.route===R.GROUPS&&state.page===R.GROUP)||(n.route===R.SETTINGS&&state.page===R.ROLES))?'aria-current="page"':''} title="${n.label}">${I(n.icon)}<span class="nav-text">${n.label}</span>${n.count?`<span class="nav-count mono">${n.count()}</span>`:''}</button>`;}).join('')+'</nav>';
    document.getElementById('app').innerHTML=`<div class="shell ${state.collapsed?'collapsed':''}"><aside class="sidebar" data-component="Sidebar"><div class="brand"><span class="brand-mark">z</span><span class="brand-word">zucco</span></div><button type="button" class="workspace-picker" data-action="workspace"><span class="workspace-symbol">${I('building')}</span><span class="grow"><span class="workspace-title">${E(Z.platform.organization.name)}</span><span class="workspace-subtitle" style="display:block">Education workspace</span></span>${I('down')}</button><div class="sidebar-scroll">${navigation}</div><div class="sidebar-footer"><button type="button" class="nav-link" data-action="help" title="Help & resources">${I('help')}<span class="nav-text">Help & resources</span><span class="grow"></span>${I('external')}</button><div class="sidebar-bottom">${A('Asilbek Bekhbudiyev')}<div class="user-info"><p class="truncate" style="font-size:11px;font-weight:500">Asilbek Bekhbudiyev</p><p class="tiny">Workspace owner</p></div></div><p class="design-label">Interactive concept · Sample data</p></div></aside>
      <div class="main-shell"><header class="topbar" data-component="Topbar"><button type="button" class="icon-btn" data-action="collapse" aria-label="${state.collapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!state.collapsed}">${I('panel')}</button><div class="breadcrumbs"><span>Workspace</span>${I('chevron')}<span>${crumbs[0]}</span>${I('chevron')}<strong>${crumbs[1]}</strong></div><div class="top-spacer"></div><label class="branch-control">${I('building')}<select id="branch-switcher" aria-label="Active branch">${['Yunusobod','Chilonzor','All branches'].map(b=>`<option ${state.branch===b?'selected':''}>${b}</option>`).join('')}</select></label><button class="header-search" type="button" data-action="command" aria-label="Global search. Command or Control K">${I('search')}<span>Search anything…</span><kbd>⌘ K</kbd></button><span class="top-divider"></span><button class="icon-btn notification-button" type="button" data-action="notifications" aria-label="Notifications, 3 unread">${I('bell')}<span class="notification-dot"></span></button>${A('Asilbek Bekhbudiyev')}</header><main class="content" id="main">${(Z.renderers[state.page]||Z.renderers[R.LEADS])()}</main></div></div>`;
    document.title=`${crumbs[1]} · Zucco`;
  };
  Z.navigate=route=>{if(!Z.renderers[route])return;state.page=route;if(location.hash.slice(1)!==route)location.hash=route;Z.render();window.scrollTo(0,0);};
  Z.toast=message=>{const box=document.getElementById('notifications');box.innerHTML=`<div class="toast">${I('checkCircle')}<span>${E(message)}</span></div>`;clearTimeout(Z.toastTimeout);Z.toastTimeout=setTimeout(()=>box.replaceChildren(),3800);};
  Z.actionDialog=html=>{const dialog=document.getElementById('action-dialog');if(dialog.open)dialog.close();dialog.innerHTML=html;dialog.showModal();};
  Z.closeAction=()=>document.getElementById('action-dialog').close();
  Z.command=()=>{const dialog=document.getElementById('command-dialog');dialog.innerHTML=`<h2 id="command-title" class="sr-only">Search Zucco</h2><label class="command-search">${I('search')}<input id="global-search" placeholder="Search pages, students, and actions…" aria-label="Search pages, students, and actions" autocomplete="off"><kbd>ESC</kbd></label><div class="command-results" id="command-results">${commandResults('')}</div><div class="command-hint">Navigate with Tab · Enter to select · Esc to close</div>`;dialog.showModal();};
  function commandResults(query){const q=query.toLowerCase();const results=[...NAV.map(n=>({label:n.label,route:n.route,icon:n.icon})),{label:'Azizbek Karimov · Student profile',route:R.STUDENT,icon:'users'},{label:'Accept a tuition payment',action:'command-payment',icon:'wallet'}].filter(n=>(n.label+' '+(Z.t?.(n.label)||'')).toLowerCase().includes(q));return results.map(n=>`<button type="button" class="command-result" data-action="${n.action||'command-go:'+n.route}">${I(n.icon)}${n.label}${I('arrow')}</button>`).join('')||'<div class="empty-state">No matching pages or students.</div>';}
  function info(title,body){Z.actionDialog(`<div class="dialog-body"><div class="dialog-title-row"><h2 id="action-title">${title}</h2>${BT('','close-action','close','ghost small')}</div>${body}</div><div class="dialog-footer">${BT('Done','close-action','check','primary')}</div>`);}
  function downloadCSV(name,rows){const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  Z.downloadCSV=downloadCSV;
  const handlers={
    ...Z.extraHandlers,
    go:([route])=>Z.navigate(route),collapse:()=>{state.collapsed=!state.collapsed;Z.render();},command:Z.command,'close-action':Z.closeAction,'close-payment':()=>document.getElementById('payment-dialog').close(),payment:Z.openPayment,
    'command-go':([route])=>{document.getElementById('command-dialog').close();Z.navigate(route);},'command-payment':()=>{document.getElementById('command-dialog').close();Z.openPayment();},
    workspace:()=>info('Zucco Academy',`<p>Your education workspace connects admissions, teaching, and finance.</p><div class="conversion-details"><div class="detail-row"><span>Active branch</span><strong>${E(state.branch)}</strong></div><div class="detail-row"><span>Academic year</span><strong>2026 — 2027</strong></div><div class="detail-row"><span>Role</span><strong>Workspace owner</strong></div></div>`),
    help:()=>info('A quicker way to work',`<div class="notification-list"><div class="notification-item">${I('search')}<div><h3>Find anything with ⌘ K or Ctrl K</h3><p>Jump between pages, find a student, or accept a payment.</p></div></div><div class="notification-item">${I('leads')}<div><h3>Keep admissions moving</h3><p>Drag lead cards between stages, or use each card’s arrow button.</p></div></div><div class="notification-item">${I('coin')}<div><h3>Reward progress as it happens</h3><p>Use +1 and +5 coin actions in the attendance journal, then save.</p></div></div></div>`),
    notifications:()=>info('Notifications',`<div class="notification-list"><div class="notification-item">${I('leads')}<div><h3>3 new leads need a first conversation</h3><p>Instagram and Telegram · 12 minutes ago</p></div></div><div class="notification-item">${I('calendar')}<div><h3>IELTS trial starts today at 14:00</h3><p>Room 201 · Madina Karimova</p></div></div><div class="notification-item">${I('wallet')}<div><h3>November tuition is due</h3><p>24 student balances need attention</p></div></div></div>`),
    'new-lead':([stage])=>Z.showNewLead(Number(stage)),convert:([id])=>Z.showConversion(id),'confirm-convert':([id])=>{Z.closeAction();Z.moveLead(id,5);},advance:([id])=>{const l=state.leads.find(l=>l.id===id);if(l)Z.moveLead(id,Math.min(5,l.stage+1));},
    'lead-view':([view])=>{state.leadView=view;Z.render();},'sort-leads':()=>{state.leads.reverse();Z.render();Z.toast('Lead order reversed');},'reset-leads':()=>{state.leadSearch='';state.leadCourse='all';state.leadAssignee='all';state.leadSource='all';Z.render();},
    'import-leads':()=>Z.actionDialog(`<form id="import-form"><div class="dialog-body"><h2 id="action-title">Import leads</h2><p>Paste one lead per line: full name, phone, course, source.</p><div class="action-form"><label class="field-label" for="import-text">Lead records</label><textarea class="input" id="import-text" name="records" required rows="6" placeholder="Diyorbek Sobirov, +998 90 111 22 33, IELTS Foundation, Instagram"></textarea><p class="caption">Accepted sources: Instagram, Telegram, Website, Referral.</p></div></div><div class="dialog-footer">${BT('Cancel','close-action')}<button type="submit" class="btn primary">Import leads</button></div></form>`),
    'profile-tab':([tab])=>{state.profileTab=tab;Z.render();document.getElementById(`profile-${tab}-tab`).focus();},
    'coin-history':()=>info('Coin activity',`<div class="conversion-details"><div class="detail-row"><span>30 Oct · Speaking performance</span><strong class="text-warning">+5 coins</strong></div><div class="detail-row"><span>28 Oct · Perfect homework</span><strong class="text-warning">+5 coins</strong></div><div class="detail-row"><span>26 Oct · Weekly progress</span><strong class="text-warning">+10 coins</strong></div><div class="detail-row"><span>Current balance</span><strong>${state.coins} Coins</strong></div></div>`),
    'edit-profile':()=>Z.actionDialog(`<form id="profile-form"><div class="dialog-body"><h2 id="action-title">Student contact note</h2><p>Add a note for the admissions and teaching teams.</p><div class="action-form"><label class="field-label" for="student-note">Note</label><textarea class="input" id="student-note" name="note" required rows="4">${E(state.studentNote||'Prefers morning classes. Parent contact: Dilshod Karimov.')}</textarea></div></div><div class="dialog-footer">${BT('Cancel','close-action')}<button type="submit" class="btn primary">Save note</button></div></form>`),
    'send-sms':()=>Z.actionDialog(`<form id="sms-form"><div class="dialog-body"><h2 id="action-title">Message Azizbek</h2><p>To +998 90 123 45 67</p><div class="action-form"><label class="field-label" for="sms-message">Message</label><textarea class="input" id="sms-message" name="message" required maxlength="320" rows="4" placeholder="Write your message…"></textarea><p class="caption">Interactive concept: messages stay in this browser.</p></div></div><div class="dialog-footer">${BT('Cancel','close-action')}<button type="submit" class="btn primary">${I('message')}Save SMS draft</button></div></form>`),
    'enroll-group':()=>info('Available groups',`<p>Azizbek is enrolled in two groups. Available November cohorts:</p><div class="conversion-details"><div class="detail-row"><span>IELTS Advanced · IA-02</span>${Z.badge('4 seats available','success')}</div><div class="detail-row"><span>Frontend Dev. · FE-03</span>${Z.badge('6 seats available','success')}</div></div>`),
    'finance-tab':([tab])=>{state.financeTab=tab;Z.render();},receipt:([id])=>Z.showReceipt(id),
    'payment-method':([method])=>{state.paymentMethod=method;document.getElementById('payment-dialog').innerHTML=Z.renderPayment();},'payment-amount':([amount])=>{state.amount=Number(amount);document.getElementById('payment-dialog').innerHTML=Z.renderPayment();},
    'review-debt':()=>info('Outstanding tuition',`<p>24 students have pending tuition. Highest balances:</p><div class="conversion-details">${[['Azizbek Karimov',600000],['Shahnoza Aliyeva',450000],['Nilufar Ahmedova',350000]].map(([name,amount])=>`<div class="detail-row"><span>${name}</span><strong class="mono text-danger">${Z.money(amount,true)}</strong></div>`).join('')}</div>`),
    'record-expense':()=>Z.actionDialog(`<form id="expense-form"><div class="dialog-body"><h2 id="action-title">Record expense</h2><p>Keep your daily cash desk balanced.</p><div class="action-form"><label class="stack"><span class="field-label">Description</span><input class="input" name="description" required maxlength="70" placeholder="e.g. Office supplies"></label><label class="stack"><span class="field-label">Amount, UZS</span><input class="input" name="amount" type="number" required min="1" step="1" max="999999999" placeholder="0"></label><label class="stack"><span class="field-label">Payment method</span><select class="select" name="method"><option>Cash</option><option>Terminal</option></select></label></div></div><div class="dialog-footer">${BT('Cancel','close-action')}<button type="submit" class="btn primary">Confirm expense</button></div></form>`),
    'export-finance':()=>downloadCSV('zucco-transactions.csv',[['Receipt','Name','Course','Amount UZS','Method','Time','Type'],...state.transactions.map(t=>[t.id,t.name,t.course,t.amount,t.method,t.time,t.kind])]),
    'export-schedule':()=>Z.exportSchedule(downloadCSV),'week-prev':()=>{state.weekOffset--;Z.render();},'week-next':()=>{state.weekOffset++;Z.render();},'week-today':()=>{state.weekOffset=0;Z.render();},'schedule-mode':([mode])=>{state.scheduleMode=mode;Z.render();},lesson:([index])=>Z.showLesson(Number(index)),'lesson-attendance':()=>{Z.closeAction();Z.navigate(R.ATTENDANCE);},'new-lesson':()=>Z.newLessonForm(),
    status:([id,status])=>Z.markStatus(id,status),reward:([id,amount])=>Z.reward(id,Number(amount)),'all-present':()=>{state.attendance.forEach(s=>s.status=Z.STATUS.PRESENT);state.unsaved=true;Z.render();Z.toast('All 10 students marked present');},'save-attendance':Z.saveJournal,
    'student-preview':([id])=>{const s=state.attendance.find(s=>s.id===id);if(!s)return;if(id==='s1')Z.navigate(R.STUDENT);else info(s.name,`<p>#${s.code} · ${state.attendanceGroup}</p><div class="conversion-details"><div class="detail-row"><span>Attendance</span><strong>${s.status[0].toUpperCase()+s.status.slice(1)}</strong></div><div class="detail-row"><span>Homework</span><strong>${s.homework}</strong></div><div class="detail-row"><span>Coin balance</span><strong>${s.coins} Coins</strong></div></div>`);}
  };
  Object.assign(handlers,Z.businessHandlers||{});
  document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const raw=button.dataset.action,[action,...args]=raw.split(':');if(!handlers[action])return;handlers[action](args);if(['status','reward','all-present'].includes(action))document.querySelector(`[data-action="${CSS.escape(raw)}"]`)?.focus();});
  document.addEventListener('input',event=>{const t=event.target;
    Z.handleExtraInput?.(t);
    if(t.id==='lead-search'){state.leadSearch=t.value;document.getElementById('leads-body').innerHTML=Z.renderLeadsBody();}
    if(t.id==='finance-search'){state.financeSearch=t.value;document.getElementById('transaction-rows').innerHTML=Z.financeRows();}
    if(t.id==='global-search')document.getElementById('command-results').innerHTML=commandResults(t.value);
    if(t.id==='payment-amount'){state.amount=Number(t.value);document.getElementById('payment-summary').innerHTML=Z.paymentSummary();document.querySelector('.drawer-footer button').innerHTML=`${I('checkCircle')}Confirm payment · ${Z.money(state.amount)} UZS`;document.getElementById('amount-error').hidden=t.validity.valid;}
    if(t.id==='payment-note')state.paymentNote=t.value;
    if(t.dataset.grade){const s=state.attendance.find(s=>s.id===t.dataset.grade);s.grade=t.value;state.unsaved=true;const status=document.getElementById('save-state');status.classList.add('unsaved');status.innerHTML=I('clock')+'Unsaved changes';}
  });
  document.addEventListener('change',event=>{const t=event.target;
    Z.handleExtraChange?.(t);
    const leadFilters={'lead-course':'leadCourse','lead-assignee':'leadAssignee','lead-source':'leadSource'};
    if(leadFilters[t.id]){state[leadFilters[t.id]]=t.value;Z.render();}
    if(t.id==='branch-switcher'){state.branch=t.value;Z.render();Z.toast(`${t.value} branch selected`);}
    if(t.id==='schedule-course'){state.scheduleCourse=t.value;Z.render();}
    if(t.id==='payment-student'){state.paymentStudent=t.value;document.getElementById('payment-dialog').innerHTML=Z.renderPayment();}
    if(t.id==='print-receipt')state.printReceipt=t.checked;
    if(t.id==='attendance-group'){state.attendanceGroup=t.value;Z.render();}
    if(t.id==='attendance-date'){state.attendanceDate=t.value;Z.render();}
    if(t.dataset.homework){state.attendance.find(s=>s.id===t.dataset.homework).homework=t.value;state.unsaved=true;Z.render();}
    if(t.id==='finance-date')Z.toast(`Date filter set to ${t.value}`);
  });
  document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();if(!form.reportValidity())return;const values=new FormData(form);
    if(['ext-form','organization-form','demo-login-form'].includes(form.id)){Z.handleExtraSubmit(form,values);return;}
    if(form.id==='payment-form')Z.recordPayment(form);
    if(form.id==='new-lead-form'){state.leads.push({id:'lead-'+crypto.randomUUID(),name:String(values.get('name')),phone:String(values.get('phone')),course:String(values.get('course')),source:String(values.get('source')),age:'Just now',stage:Number(form.dataset.stage),assignee:'Madina Karimova'});Z.closeAction();Z.render();Z.toast('New lead added to the pipeline');}
    if(form.id==='import-form'){const rows=String(values.get('records')).split('\n').map(r=>r.split(',').map(v=>v.trim())).filter(r=>r.length>=2&&r[0]&&r[1]);rows.forEach(([name,phone,course='IELTS Foundation',source='Website'])=>state.leads.push({id:'lead-'+crypto.randomUUID(),name,phone,course,source,age:'Just now',stage:0,assignee:'Madina Karimova'}));Z.closeAction();Z.render();Z.toast(`${rows.length} leads imported`);}
    if(form.id==='profile-form'){state.studentNote=String(values.get('note'));Z.closeAction();Z.toast('Student contact note saved');}
    if(form.id==='sms-form'){state.smsDraft=String(values.get('message'));Z.closeAction();Z.toast('SMS draft saved in this prototype');}
    if(form.id==='expense-form'){const amount=Number(values.get('amount'));state.expenses+=amount;state.transactions.unshift({id:'EXP-00'+(87+state.transactions.filter(t=>t.kind==='expense').length-2),name:String(values.get('description')),course:'Operating expenses',amount,method:String(values.get('method')),time:'10:48',kind:'expense'});Z.closeAction();Z.render();Z.toast('Expense recorded');}
    if(form.id==='lesson-form')Z.saveNewLesson(values);
  });
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!document.getElementById('command-dialog').open)Z.command();}if(event.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const tabs=[...event.target.parentElement.querySelectorAll('[role="tab"]')];const index=(tabs.indexOf(event.target)+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[index].click();}});
  let draggedLead=null;
  document.addEventListener('dragstart',event=>{const card=event.target.closest('[data-lead]');if(!card)return;draggedLead=card.dataset.lead;event.dataTransfer.setData('text/plain',draggedLead);event.dataTransfer.effectAllowed='move';card.classList.add('dragging');});
  document.addEventListener('dragover',event=>{const col=event.target.closest('[data-stage]');if(col&&draggedLead){event.preventDefault();event.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(n=>n.classList.remove('drop-target'));col.classList.add('drop-target');}});
  document.addEventListener('drop',event=>{const col=event.target.closest('.kanban-column[data-stage]');if(col&&draggedLead){event.preventDefault();Z.moveLead(draggedLead,Number(col.dataset.stage));draggedLead=null;}});
  document.addEventListener('dragend',()=>{draggedLead=null;document.querySelectorAll('.drop-target,.dragging').forEach(n=>n.classList.remove('drop-target','dragging'));});
  window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(Z.renderers[route]&&state.page!==route){state.page=route;Z.render();}});
  const initial=location.hash.slice(1);state.page=Z.renderers[initial]?initial:R.DASHBOARD;
  Z.render();
})();
